<?php
namespace App\Http\Controllers\Api\V1;
use App\Http\Controllers\Controller;use App\Models\Category;use App\Models\Order;use App\Models\PaymentTender;use App\Models\Product;use App\Models\PrintServiceSetting;use App\Services\OrderService;use Illuminate\Http\JsonResponse;use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;use Illuminate\Support\Facades\Hash;use Illuminate\Support\Str;
class MobilePosController extends Controller{
public function login(Request $request):JsonResponse{$data=$request->validate(['email'=>'required|email','password'=>'required|string']);$user=\App\Models\User::where('email',$data['email'])->first();abort_unless($user&&Hash::check($data['password'],$user->password),422,'Invalid credentials.');$token=Str::random(80);DB::table('mobile_pos_tokens')->updateOrInsert(['user_id'=>$user->id],['token_hash'=>hash('sha256',$token),'device_name'=>$request->input('device_name'),'last_used_at'=>now(),'updated_at'=>now(),'created_at'=>now()]);return response()->json(['token'=>$token,'user'=>['id'=>$user->id,'name'=>$user->name,'email'=>$user->email]]);}
public function bootstrap(Request $request):JsonResponse{$this->authenticate($request);$products=Product::with(['category','modifiers','recipes.ingredient'])->where('is_active',true)->orderBy('display_order')->get()->map(function(Product $p){$row=$p->toArray();$row['image_url']=$p->image?asset('storage/'.$p->image):null;return array_merge($row,$p->stockStatus());});return response()->json(['server_time'=>now()->toIso8601String(),'categories'=>Category::where('is_active',true)->orderBy('display_order')->get(),'products'=>$products,'payment_tenders'=>PaymentTender::where('is_active',true)->orderBy('display_order')->orderBy('name')->get(),'print_settings'=>PrintServiceSetting::getSetting(),'orders'=>Order::with(['items.product','payments.tender'])->latest()->limit(100)->get()]);}
public function sync(Request $request,OrderService $orders):JsonResponse{$user=$this->authenticate($request);$data=$request->validate(['orders'=>'array|max:100','orders.*.client_id'=>'required|string|max:100','orders.*.order_type'=>'nullable|string|max:50','orders.*.table_number'=>'nullable|string|max:50','orders.*.customer_name'=>'nullable|string|max:255','orders.*.customer_contact'=>'nullable|string|max:255','orders.*.customer_address'=>'nullable|string|max:500','orders.*.notes'=>'nullable|string|max:500','orders.*.discount_amount'=>'nullable|numeric|min:0','orders.*.items'=>'required|array|min:1','orders.*.items.*.product_id'=>'required|integer|exists:products,id','orders.*.items.*.quantity'=>'required|integer|min:1','orders.*.items.*.modifiers'=>'nullable|array']);$results=[];foreach($data['orders']??[] as $payload){$existing=DB::table('mobile_pos_sync_records')->where('client_id',$payload['client_id'])->first();if($existing){$results[]=['client_id'=>$payload['client_id'],'order_id'=>$existing->order_id,'status'=>'already_synced'];continue;}try{$order=DB::transaction(function()use($orders,$payload,$user){$d=$payload;unset($d['client_id']);$d['user_id']=$user->id;auth()->setUser($user);$order=$orders->createOrder($d);DB::table('mobile_pos_sync_records')->insert(['client_id'=>$payload['client_id'],'order_id'=>$order->id,'user_id'=>$user->id,'created_at'=>now(),'updated_at'=>now()]);return $order;});$results[]=['client_id'=>$payload['client_id'],'order_id'=>$order->id,'status'=>'synced'];}catch(\Throwable $e){report($e);$results[]=['client_id'=>$payload['client_id'],'status'=>'error','message'=>$e->getMessage()];}}return response()->json(['server_time'=>now()->toIso8601String(),'orders'=>$results]);}
private function authenticate(Request $request){$plain=$request->bearerToken();abort_unless($plain,401,'Mobile POS token required.');$row=DB::table('mobile_pos_tokens')->where('token_hash',hash('sha256',$plain))->first();abort_unless($row,401,'Invalid mobile POS token.');DB::table('mobile_pos_tokens')->where('id',$row->id)->update(['last_used_at'=>now()]);return \App\Models\User::findOrFail($row->user_id);}}
